/* Markup: <div class="fx-prismcut" data-text="PRISM">PRISM</div> */

/* Colour tokens — override to re-skin the effect:
   --ink    main text colour (defaults to currentColor)
   --ink-2  primary accent   --ink-3  secondary accent */
:root { --ink: currentColor; --ink-2: #FF4FD8; --ink-3: #4FF8FF; }

/* 45 Prism-Cut */
.fx-prismcut {
  position: relative;
  font: 600 32px/1.1 JetBrains Mono, monospace;
  letter-spacing: .12em;
  color: var(--ink);
}
.fx-prismcut:before, .fx-prismcut:after {
  content: attr(data-text);
  position: absolute;
  inset: 0;
  pointer-events: none;
}
.fx-prismcut:before {
  color: var(--ink-2);
  clip-path: polygon(0 0, 66% 0, 46% 100%, 0 100%);
  animation: fx-prismcut-a 3s ease-in-out infinite;
}
.fx-prismcut:after {
  color: var(--ink-3);
  clip-path: polygon(42% 0, 100% 0, 100% 100%, 24% 100%);
  animation: fx-prismcut-b 3s ease-in-out infinite;
}
@keyframes fx-prismcut-a {
  0%,to {
    transform: translate(0);
    opacity: .35;
  }
  50% {
    transform: translate(-7px, -2px);
    opacity: .85;
  }
}
@keyframes fx-prismcut-b {
  0%,to {
    transform: translate(0);
    opacity: .35;
  }
  50% {
    transform: translate(7px, 2px);
    opacity: .85;
  }
}
